using System.Xml.Linq;
using Newtonsoft.Json.Linq;
using TiaMcp.Openness.V21;

int count = 0;
void Check(bool condition, string description) { if (!condition) throw new Exception(description); count++; }
JObject Identity(string path) => new JObject { ["objectPath"] = path, ["name"] = "Repeated" };
Check(HmiInspectionRules.Profiles.Length == 6, "Six independent profiles must remain explicit.");
Check(HmiInspectionRules.Profile("classic", "SIMATIC HMI TP1200 Comfort") == "classic-comfort", "Classic profile from native catalog classification.");
Check(HmiInspectionRules.Profile("unified", "SIMATIC Unified PC V21") == "unified-pc", "Unified PC independently classified.");
Check(HmiInspectionRules.Profile("classic", "SIMATIC Unified PC V21") == "unknown", "No family inference from a mismatched target.");
Check(HmiInspectionRules.Profile("unified", "6AV0000") == "unknown", "Article numbers do not prove a profile without catalog evidence.");
Check(HmiInspectionRules.Escape("Screen/A% B") == "Screen%2FA%25%20B", "Paths escape separators and percent characters.");
Check(HmiInspectionRules.NamedChildPath("/folders", null) == null && HmiInspectionRules.NamedChildPath("/folders", "") == null, "Unreadable or empty folder names cannot manufacture identities.");
Check(HmiInspectionRules.NamedChildPath("/folders", "A/B") == "/folders/A%2FB", "Valid native folder names preserve escaped scope boundaries.");
var catalogDefinition = new JObject { ["typeIdentifier"] = "OrderNumber:Panel/21.0.1", ["typeIdentifierNormalized"] = "OrderNumber:Panel/V21.0.1", ["typeName"] = "MTP700 Unified Comfort", ["version"] = "21.0.1" };
Check(HmiInspectionRules.ExactCatalogDefinition("OrderNumber:Panel/21.0.1", new[] { catalogDefinition }, true)?.Value<string>("typeName") == "MTP700 Unified Comfort", "Hardware identity is joined to the exact native catalog entry before profile classification.");
Check(HmiInspectionRules.ExactCatalogDefinition("OrderNumber:Panel/V21.0.1", new[] { catalogDefinition }, true) != null, "Only the catalog's explicit normalized identifier is an alternate exact match.");
Check(HmiInspectionRules.ExactCatalogDefinition("OrderNumber:Panel/20.0.0", new[] { catalogDefinition }, true) == null, "A same-article different-version catalog entry cannot supply a profile.");
Check(HmiInspectionRules.ExactCatalogDefinition("OrderNumber:Panel/21.0.1", new[] { catalogDefinition, catalogDefinition }, true) == null && HmiInspectionRules.ExactCatalogDefinition("OrderNumber:Panel/21.0.1", new[] { catalogDefinition }, false) == null, "Duplicate exact matches and incomplete catalog enumeration remain unresolved.");
JObject Catalog(string path, string typeName) => new JObject { ["sourcePath"] = path, ["catalogIdentifier"] = "OrderNumber:fixture/21.0.1", ["classification"] = typeName, ["runtimeVersion"] = "21.0.1" };
var catalog = new[] { Catalog("/device/items/Panel", "MTP700 Unified Comfort") };
var selectedCatalog = HmiInspectionRules.CatalogSelection("unified", catalog, true, 1, "nativeOwningDeviceCatalog");
Check(selectedCatalog.Value<string>("profile") == "unified-comfort" && selectedCatalog["evidence"]["candidates"][0].Value<string>("sourcePath") == "/device/items/Panel", "Unique same-device catalog classification retains exact native provenance.");
Check(HmiInspectionRules.CatalogSelection("unified", catalog.Concat(catalog), true, 1, "nativeOwningDeviceCatalog").Value<string>("profile") == "unknown", "Multiple same-family catalog candidates do not establish runtime association.");
Check(HmiInspectionRules.CatalogSelection("unified", catalog, true, 2, "nativeOwningDeviceCatalog").Value<string>("profile") == "unknown", "Two runtimes in one owning device cannot borrow a single sibling catalog identity.");
Check(HmiInspectionRules.CatalogSelection("unified", catalog, false, 1, "nativeOwningDeviceCatalog").Value<string>("profile") == "unknown", "One candidate observed before a traversal bound is not a unique complete catalog proof.");
Check(HmiInspectionRules.CatalogSelection("unified", Array.Empty<JObject>(), true, 1, "nativeOwningDeviceCatalog").Value<string>("profile") == "unknown", "Missing catalog data remains unknown.");
Check(HmiInspectionRules.CatalogSelection("classic", catalog, true, 1, "nativeOwningDeviceCatalog").Value<string>("profile") == "unknown", "A sibling catalog from another family cannot establish this runtime profile.");
var unresolved = HmiInspectionRules.Reference("/item", "binding", "Tag", "Repeated", Array.Empty<JObject>(), false);
Check(unresolved.Value<string>("resolution") == "unresolved" && unresolved["target"].Type == JTokenType.Null, "Missing native bindings stay unresolved.");
var ambiguous = HmiInspectionRules.Reference("/item", "binding", "Tag", "Repeated", new[] { Identity("/A/Repeated"), Identity("/B/Repeated") }, false);
Check(ambiguous.Value<string>("resolution") == "ambiguous" && ((JArray)ambiguous["targetCandidates"]).Count == 2, "Duplicate native foreign-key matches remain ambiguous.");
var dynamic = HmiInspectionRules.Reference("/item", "binding", "Tag", "Repeated", new[] { Identity("/A/Repeated") }, true);
Check(dynamic.Value<string>("resolution") == "dynamic" && dynamic["target"].Type == JTokenType.Null, "A dynamic reference does not become exact because one candidate exists.");
var explicitBinding = HmiInspectionRules.Reference("/item", "binding", "Tag", "Repeated", new[] { Identity("/A/Repeated") }, false);
Check(explicitBinding.Value<string>("evidence") == "nativeConfirmed" && !explicitBinding.Value<bool>("automaticRewiringAllowed"), "Read-only reference evidence does not grant mutation permission.");
var incompleteBinding = HmiInspectionRules.Reference("/item", "binding", "Tag", "Repeated", new[] { Identity("/A/Repeated") }, false, candidatesComplete: false);
Check(incompleteBinding.Value<string>("resolution") == "unresolved" && incompleteBinding["target"].Type == JTokenType.Null && ((JArray)incompleteBinding["targetCandidates"]).Count == 1, "A sole observed foreign-key candidate does not prove uniqueness in an incomplete scope.");
const string discreteType = "Siemens.Engineering.HmiUnified.HmiAlarm.HmiDiscreteAlarm";
IEnumerable<JObject> AlarmCandidates(string name) => name == "Repeated" ? new[] { Identity("/A/Repeated") } : name == "Duplicate" ? new[] { Identity("/A/Duplicate"), Identity("/B/Duplicate") } : Array.Empty<JObject>();
var alarmProperties = new JObject { ["RaisedStateTag"] = "Repeated", ["RaisedStateTagBitNumber"] = 3, ["AcknowledgmentStateTag"] = "Missing", ["AcknowledgmentControlTag"] = "Duplicate" };
var alarmEdges = HmiInspectionRules.UnifiedAlarmReferences(discreteType, "/alarm", alarmProperties, new JArray("Repeated", "", "Tags(\"Repeated\")"), AlarmCandidates, true).ToList();
Check(alarmEdges.Count == 5 && alarmEdges[0].Value<string>("resolution") == "resolved" && alarmEdges[0].Value<int>("bitNumber") == 3, "Documented raised-state tag and bit refer to the exact unique HMI tag.");
Check(alarmEdges[1].Value<string>("resolution") == "unresolved" && alarmEdges[2].Value<string>("resolution") == "ambiguous", "Missing alarm tags and repeated candidates retain distinct unresolved outcomes.");
Check(alarmEdges[3].Value<string>("sourceProperty") == "AlarmParameterTags[0]" && alarmEdges[4].Value<string>("resolution") == "unresolved", "Alarm parameters retain indices, skip empty slots and never execute expression-like text.");
Check(HmiInspectionRules.UnifiedAlarmReferences(discreteType, "/alarm", alarmProperties, new JArray(), AlarmCandidates, false).All(e => e.Value<string>("resolution") == "unresolved" && e["target"].Type == JTokenType.Null), "Incomplete tag scope prevents all alarm foreign-key promotions.");
Check(HmiInspectionRules.UnifiedAlarmReferences("ClassicAlarm", "/alarm", alarmProperties, new JArray(), AlarmCandidates, true).Count() == 0, "Unified alarm semantics are not applied to Classic or unknown native types.");
var unreadableAlarm = HmiInspectionRules.UnifiedAlarmReferences(discreteType, "/alarm", new JObject { ["RaisedStateTag"] = new JObject { ["value"] = "Repeated", ["truncated"] = true }, ["AcknowledgmentStateTag"] = "", ["AcknowledgmentControlTag"] = "" }, new JObject { ["expanded"] = false }, AlarmCandidates, true).ToList();
Check(unreadableAlarm.All(e => e.Value<string>("resolution") == "unresolved") && unreadableAlarm[0]["rawValue"].Value<bool>("truncated"), "Truncated scalar and unsupported parameter list shapes retain evidence without bindings.");
var analogEdges = HmiInspectionRules.UnifiedAlarmReferences("Siemens.Engineering.HmiUnified.HmiAlarm.HmiAnalogAlarm", "/alarm", alarmProperties, new JArray(), AlarmCandidates, true).ToList();
Check(analogEdges.Count == 1 && analogEdges[0].Value<string>("sourceProperty") == "RaisedStateTag", "Analog alarms use their documented trigger property without borrowing discrete acknowledgment semantics.");
var portObservation = HmiInspectionRules.UnresolvedNativeReference("/faceplate", "hmiFaceplatePort", "Interface/Value", new JValue("Repeated"), "unqualified");
Check(portObservation.Value<string>("resolution") == "unresolved" && portObservation["target"].Type == JTokenType.Null && portObservation.Value<string>("nativeSpelling") == "Repeated", "A faceplate port's same-name string stays an explicit unresolved observation.");
Check(HmiInspectionRules.DirectTagBinding(new JObject { ["UseIndirectAddressing"] = false }, new JObject { ["IsFormulaSelected"] = false }), "A directly configured tag binding requires native direct-addressing and non-formula readback.");
Check(!HmiInspectionRules.DirectTagBinding(new JObject { ["UseIndirectAddressing"] = false }, new JObject { ["IsFormulaSelected"] = true, ["Formula"] = "'Other' + 2" }), "A formula-bearing tag dynamic cannot be promoted from its nominal Tag field.");
Check(!HmiInspectionRules.DirectTagBinding(new JObject { ["UseIndirectAddressing"] = false }, null), "Missing native converter metadata keeps the binding unresolved.");
var sourceScope = HmiInspectionRules.SourceCoverage("unified", "Siemens.Engineering.HmiUnified.TextGraphicList.HmiTextList", "/HMI", "/HMI/textLists/Selected");
Check(sourceScope.Value<string>("scope") == "nativeComposition" && !sourceScope.Value<bool>("selectedObjectOnly") && sourceScope.Value<string>("requestedObjectPath") == "/HMI/textLists/Selected", "An exact requested list must not mislabel a native collection export as selected-only.");
Check(!sourceScope.Value<bool>("complete") && sourceScope["omissions"].Any(p => p.Value<string>().Contains("formatted")), "Native formatted-text omissions prevent complete source claims.");
var classicSourceScope = HmiInspectionRules.SourceCoverage("classic", "Siemens.Engineering.Hmi.TextGraphicList.TextList", "/HMI", "/HMI/textLists/Selected");
Check(classicSourceScope.Value<bool>("selectedObjectOnly") && !classicSourceScope.Value<bool>("complete"), "Classic selected-object export scope is independent of full preservation qualification.");
var xml = XDocument.Parse("<Document><Hmi.Screen.Screen ID='0'><AttributeList><Name>Main</Name></AttributeList><ObjectList><Hmi.Screen.Group ID='1'><AttributeList><Name>Group/A</Name></AttributeList><ObjectList><Hmi.Screen.IOField ID='2'><AttributeList><Name>Repeated</Name><Left>12</Left></AttributeList><ObjectList><UnknownBinding><TagName>Missing</TagName></UnknownBinding></ObjectList></Hmi.Screen.IOField></ObjectList></Hmi.Screen.Group><Hmi.Screen.IOField ID='3'><AttributeList><Name>Repeated</Name></AttributeList></Hmi.Screen.IOField><Unknown ID='4'><AttributeList><Name>DoNotGuess</Name></AttributeList></Unknown></ObjectList></Hmi.Screen.Screen></Document>");
var rows = HmiInspectionRules.ClassicItems(xml, "/screen", "fixture-hash", () => true).ToList();
Check(rows.Count == 3, "Only the supported named screen payload objects are emitted; unknown XML remains in its original artifact.");
Check(rows.Single(r => r.Value<string>("objectPath") == "/screen/exportItems/2").Value<string>("parentPath") == "/screen/exportItems/1", "Nested item containment follows native export hierarchy.");
Check(rows.Count(r => r.Value<string>("name") == "Repeated") == 2 && rows.Select(r => r.Value<string>("objectPath")).Distinct().Count() == 3, "Export-local identities preserve valid repeated member names.");
Check(rows[1]["referencePayloads"].Any(p => p.Value<string>("nativeSpelling") == "Missing" && p.Value<string>("resolution") == "unresolved"), "Unknown/broken reference text is retained without invented targets.");
Check(!rows[0]["referencePayloads"].Any(p => p.Value<string>("nativeSpelling") == "Missing"), "A child's unknown binding is not attributed to its parent group.");
var classicLinks = XDocument.Parse("<Document><Hmi.Screen.IOField ID='2'><AttributeList><ObjectName>Widget</ObjectName></AttributeList><LinkList><ProcessTag TargetID='@OpenLink'><TargetObject><Name>Repeated</Name></TargetObject></ProcessTag></LinkList><EventList><Navigation><ScreenName>Overview_B</ScreenName></Navigation></EventList></Hmi.Screen.IOField></Document>");
var linkPayloads = (JArray)HmiInspectionRules.ClassicItems(classicLinks, "/screen", "hash", () => true).Single()["referencePayloads"];
Check(linkPayloads.Any(p => p.Value<string>("property").Contains("ProcessTag") && p["rawAttributes"].Any(a => a.Value<string>("value") == "@OpenLink") && p.Value<string>("resolution") == "unresolved"), "Classic link spelling and native link attributes remain retained evidence without an invented parser.");
Check(linkPayloads.Any(p => p.Value<string>("nativeSpelling") == "Overview_B" && p.Value<string>("resolution") == "unresolved"), "Classic navigation source is visible and unresolved even when a same-named screen exists.");
var clippedXml = XDocument.Parse("<Document><Hmi.Screen.IOField ID='2'><AttributeList><Name>Widget</Name><LongText>" + new string('x', 8193) + "</LongText></AttributeList><LinkList>" + string.Concat(Enumerable.Range(0, 66).Select(i => "<Tag>Value" + i + "</Tag>")) + "</LinkList></Hmi.Screen.IOField></Document>");
var clippedRow = HmiInspectionRules.ClassicItems(clippedXml, "/screen", "hash", () => true).Single();
Check(clippedRow["metadataCoverage"].Value<bool>("scalarPropertiesTruncated") && clippedRow["metadataCoverage"].Value<bool>("referencePayloadsTruncated") && ((JArray)clippedRow["referencePayloads"]).Count == 64, "Clipped Classic scalar and reference previews report their limits instead of claiming complete metadata.");
int visited = 0;
Check(HmiInspectionRules.ClassicItems(xml, "/screen", "fixture-hash", () => ++visited <= 1).Count() == 0 && visited == 2, "Native XML traversal stops at the requested bound.");
Check(HmiInspectionRules.Section("hmiScreenItem") == "items", "Exact identity routes to item inspection.");
var nativeShape = XDocument.Parse("<Document><Hmi.Screen.Screen ID='0'><AttributeList><Name>Overview_A</Name></AttributeList><ObjectList><Hmi.Screen.ScreenLayer ID='3' CompositionName='Layers'><AttributeList><Name>Qualification</Name></AttributeList><ObjectList><Hmi.Screen.Rectangle ID='4' CompositionName='ScreenItems'><AttributeList><ObjectName>RepeatedItem</ObjectName><Left>30</Left><Top>40</Top><Width>120</Width><Height>60</Height></AttributeList></Hmi.Screen.Rectangle></ObjectList></Hmi.Screen.ScreenLayer></ObjectList></Hmi.Screen.Screen></Document>");
var actualRows = HmiInspectionRules.ClassicItems(nativeShape, "/nativeScreen", "native-export-hash", () => true).ToList();
Check(actualRows.Count == 2 && actualRows[0].Value<string>("kind") == "hmiScreenLayer" && actualRows[0].Value<bool>("structural"), "Native ScreenLayer remains an explicit structural container.");
Check(actualRows[1].Value<string>("name") == "RepeatedItem" && actualRows[1]["properties"].Value<string>("Left") == "30" && actualRows[1].Value<string>("parentPath") == "/nativeScreen/exportItems/3", "Observed V21 ObjectName rectangle and exact coordinates are retained.");
var templateShape = XDocument.Parse("<Document><Hmi.Screen.ScreenTemplate ID='0'><AttributeList><Name>Overview_A</Name></AttributeList><ObjectList><Hmi.Screen.ScreenLayer ID='1' CompositionName='Layers'><AttributeList><Name>Qualification</Name></AttributeList><ObjectList><Hmi.Screen.Rectangle ID='2' CompositionName='ScreenItems'><AttributeList><ObjectName>RepeatedItem</ObjectName></AttributeList></Hmi.Screen.Rectangle></ObjectList></Hmi.Screen.ScreenLayer></ObjectList></Hmi.Screen.ScreenTemplate></Document>");
var templateRows = HmiInspectionRules.ClassicItems(templateShape, "/template", "template-hash", () => true).ToList();
Check(templateRows.Count == 2 && templateRows.All(r => r.Value<string>("nativeType") != "Hmi.Screen.ScreenTemplate") && templateRows[0].Value<string>("parentPath") == "/template", "A template's own export root is its owner, not an item, like a regular screen.");
Check(HmiInspectionRules.ScalarSymbolPath("\"Data.Block\".Motor.Speed").SequenceEqual(new[] { "Data.Block", "Motor", "Speed" }), "Quoted PLC names retain dot boundaries for explicit symbolic binding.");
Check(HmiInspectionRules.ScalarSymbolPath("SharedValue").Single() == "SharedValue", "Plain symbolic PLC foreign key parsed without name rewriting.");
foreach (string unsupported in new[] { "DB.Values[Index]", "DB.Values[3]", "#Local", "DB..Value", "DB.Value+Other", "DB.", "\"unterminated" })
    Check(HmiInspectionRules.ScalarSymbolPath(unsupported) == null, "Dynamic, array, malformed and local symbolic paths stay unresolved: " + unsupported);
try { HmiInspectionRules.Section("plc"); throw new Exception("Unexpected cross-family route."); } catch (ArgumentException) { count++; }
JObject Diagnostic(string state = "Information", params JObject[] children) => new JObject {
    ["state"] = state, ["description"] = "native diagnostic", ["path"] = "/HMI", ["children"] = new JArray(children) };
JArray CaptureDiagnostics(IEnumerable<JObject> messages, int maximumMessages = 500, int maximumDepth = 32) =>
    HmiCompilerDiagnostics.Capture(messages, row => row.Value<string>("state"), row => row.Value<string>("description"),
        row => row.Value<string>("path"), row => ((JArray)row["children"]).Cast<JObject>(), maximumMessages, maximumDepth);
Check(HmiCompilerDiagnostics.IsComplete(CaptureDiagnostics(Array.Empty<JObject>())), "An observed empty diagnostic collection is complete.");
Check(!HmiCompilerDiagnostics.IsComplete(CaptureDiagnostics(null)), "An unavailable diagnostic collection is explicitly incomplete.");
var fullBudget = Enumerable.Range(0, 500).Select(_ => Diagnostic()).ToArray();
Check(HmiCompilerDiagnostics.IsComplete(CaptureDiagnostics(fullBudget)), "Exactly 500 messages pass only after the native enumerator proves no next message.");
var overflow = CaptureDiagnostics(fullBudget.Concat(new[] { Diagnostic("Error") }));
Check(overflow.Count == 501 && !HmiCompilerDiagnostics.IsComplete(overflow) && overflow.Last.Value<bool>("diagnosticCaptureIncomplete"), "A hidden 501st error leaves an explicit incomplete marker, never a complete success tree.");
var nestedBudget = CaptureDiagnostics(new[] { Diagnostic("Information", Diagnostic(), Diagnostic()), Diagnostic("Error") }, maximumMessages: 3);
Check(!HmiCompilerDiagnostics.IsComplete(nestedBudget), "Message budget is shared across parent, children and later siblings.");
var nestedDepth = CaptureDiagnostics(new[] { Diagnostic("Information", Diagnostic("Information", Diagnostic("Error"))) }, maximumDepth: 2);
Check(!HmiCompilerDiagnostics.IsComplete(nestedDepth), "A diagnostic beyond the depth bound leaves an explicit incomplete marker.");
Check(HmiCompilerDiagnostics.IsComplete(CaptureDiagnostics(new[] { Diagnostic("Information", Diagnostic()) }, maximumDepth: 2)), "An empty child collection at the depth boundary remains complete.");
var nativeError = CaptureDiagnostics(new[] { Diagnostic("Error") });
Check(HmiCompilerDiagnostics.IsComplete(nativeError) && nativeError[0].Value<string>("state") == "Error", "Capture completeness retains native errors and does not imply compile success.");
ClassicScreenInventoryTests.Run(Check);
Console.WriteLine($"{count} HMI inspection contract checks passed. Native qualification remains separate.");
